WITH cleaned AS (SELECT id, customer_id, device, country, DAYOFWEEK(started_at) AS started_at_dayofweek, COALESCE(country, 'NONE') AS country_clean FROM sessions WHERE browser IS NOT NULL), enriched AS (SELECT s.id, s.customer_id, s.device, s.country, s.country_clean, p.signup_date, p.name, p.email FROM cleaned s INNER JOIN customers p ON s.customer_id = p.id), scored AS (SELECT id, customer_id, device, country, email, ROW_NUMBER() OVER (PARTITION BY country ORDER BY signup_date DESC, id ASC) AS seq_no, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY signup_date ASC, id ASC) AS event_seq, ROW_NUMBER() OVER (PARTITION BY country ORDER BY signup_date ASC, id ASC) AS row_seq, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('MONTH', signup_date) ORDER BY signup_date DESC, id ASC) AS row_seq_2 FROM enriched), scored_sessions AS (SELECT id, device, email, event_seq, row_seq_2, MIN(seq_no) OVER w_running AS last4_min_seq_no, MAX(seq_no) OVER w_running AS last4_max_seq_no, AVG(seq_no) OVER w_running AS last4_avg_seq_no, ROW_NUMBER() OVER w_hist AS row_seq_3 FROM scored WHERE seq_no BETWEEN 4 AND 6 WINDOW w_running AS (PARTITION BY customer_id ORDER BY row_seq_2 ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_hist AS (ORDER BY event_seq ASC, id ASC)) SELECT CASE WHEN row_seq_3 >= 8 THEN 'HIGH' ELSE 'LOW' END AS row_seq_3_tier, COUNT(*) FILTER (WHERE device = 'tablet') AS tablet_rows, COUNT(*) AS num_rows, COUNT(DISTINCT id) AS distinct_ids FROM scored_sessions GROUP BY CASE WHEN row_seq_3 >= 8 THEN 'HIGH' ELSE 'LOW' END HAVING COUNT(*) FILTER (WHERE device = 'tablet') >= 1;
